from pathlib import Path
import json,copy,re,sys
O=Path(__file__).resolve().parent;B=O.parents[3];sys.path.insert(0,str(B));from run_exhaustive import validate_answer
SS=json.loads((O/'source.json').read_text());S={s['number']:s for s in SS};A={};p=lambda t:'<p>'+t+'</p>\n'
T='Ces dispositions s’appliquent à compter de l’entrée en vigueur de la réforme, y compris aux demandes en cours sans nouveau dépôt ni reprise des délais déjà courus. Les aides attribuées, les conventions valablement conclues, les droits des occupants et des tiers et les recours restent régis par leurs règles propres.'
def effect(n,mid,kind,sq,pq,before,after):
 for quote_name in ['sq','pq']:
  text=S[n]['source_xml']if quote_name=='sq'else None
  if text and sq not in text and sq.replace('’',"'")in text:sq=sq.replace('’',"'")
 return {'kind':kind,'measure_id':mid,'description':after,'before':before,'after':after,'source_quote':sq,'proposed_quote':pq,'unit':'legal_duty','affected_population':'Organismes et situations entrant dans le champ exact de '+n+'.','conditions_and_transition':'Entrée en vigueur future, demandes en cours sans reprise des délais ; contrats, aides et droits acquis préservés selon le texte entier.','replacement_or_new_burdens':'Aucune déclaration de remplacement ni prélèvement nouveau ; les garanties de fond et contrôles distincts demeurent. Coût net non chiffré.'}
def add(n,body,why,notes,benefit,classification,es=[],removed=None,repeal=False):
 s=S[n];r={k:s[k]for k in ['code_id','source_id','source_sha256','number']};r.update(status='retained_unchanged'if body is None else'rewrite_draft',proposed_xml=body,reason=why,review_notes=notes,benefit_review=benefit,substantive_impact={'version':1,'classification':classification,'assessment':why+' Le bilan distingue la charge nouvelle retirée des seules coordinations de décisions déjà intégrées ; le nombre d’articles n’est pas un gain.','scope_limitations':'Périmètre borné aux agréments et sociétés d’économie mixte. Aucune modification fiscale chiffrée, de loyer, de compensationSIEG ou de budget national. Les règles européennes, conventions et droits des occupants restent à leur champ propre ; pas de clôture globale des renvois hors lot.','new_burdens_review':'Aucun contrôle, dossier périodique, taxe ou attestation de remplacement. Le maintien des informations financières nécessaires n’est pas présenté comme une réduction. Les échanges déjà légalement disponibles relèvent duCRPA et ne sont pas recomptés comme une nouvelle coupe.','effects':es})
 if repeal:r.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=why)
 elif removed:r.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
 A[n]=r
# Retirer les deux mécanismes de concentration forcée, sans effacer les contrôles d’irrégularité ou les opérations acquises.
n='L481-1-1';body=p('Le présent article est abrogé à compter de l’entrée en vigueur de la loi portant cette abrogation.')+p('À compter de cette date, la taille du parc, le volume de construction sur dix ans et la contribution insuffisante aux objectifs qui étaient visés au premier alinéa du I ne peuvent plus fonder, au titre du présent article, un retrait d’agrément ni une nouvelle mise en demeure de céder ou d’acquérir des logements. Les procédures en cours fondées sur ces seuls critères prennent fin sans déclaration de remplacement. Les contrôles, mesures et sanctions fondés sur des manquements distincts, notamment des irrégularités financières, la qualité de gestion ou le non-respect des conditions d’agrément, demeurent applicables.')+p('Les contrats d’acquisition, engagements financiers et aides valablement conclus ou attribués avant cette date, ainsi que les créances et recours qui en découlent, conservent leurs effets. Les opérations déjà valablement décidées demeurent régies par leurs règles antérieures, notamment le contrôle de la qualité technique et financière de l’acquéreur, la limite d’accroissement de vingt pour cent sauf accord de sa part, sa compétence géographique, l’aide déjà accordée et le régime de fixation du prix et de recours au juge. Aucune nouvelle mise en demeure ou cession forcée ne peut toutefois être engagée après cette date sur le seul fondement abrogé. Un agrément déjà retiré n’est pas rétabli automatiquement.')+p('Les regroupements et acquisitions volontaires restent possibles selon leurs règles propres. Les concours ouverts par l’article L. 452-1 demeurent accessibles aux futures opérations qui en remplissent les conditions, sans obligation nouvelle de regroupement. Les conventions des logements, les droits des locataires et les contrôles de l’Agence nationale de contrôle du logement social restent applicables.')
add(n,body,'Supprimer le retrait d’agrément et les acquisitions forcées fondés sur la petite taille, le faible rythme de construction et la contribution insuffisante au titre de cet article.','I etII, seuils1500/500/dixans, exception des groupes, garanties20%, sixmois/prix/recours lus entiers. Ces seuils perdent leur fonction de contrainte pour l’avenir ; ils ne sont pas transformés en quotasSRU. L342-2/12 etL452-1/2-1 lus avec leurs projets : contrôle de gestion et concours volontaires distincts conservés. La transition ne supprime pas les contrats ou créances antérieurs et ne restaure aucun agrément retiré.','La disparition entière de ce mécanisme rend inutile son exception pour les sociétés déjà groupées sans rendre ces sociétés moins favorisées. Les aides déjà attribuées et les futurs concours légaux pour opérations volontaires restent accessibles, avec protection des occupants et recours sur le prix ancien.','material_reduction',[effect(n,'sem-concentration-forcee-supprimee','obligation_removed',"se voir retirer son agrément par arrêté du ministre chargé du logement",'ne peuvent plus fonder, au titre du présent article, un retrait d’agrément','Retrait possible et acquisition imposée si petite taille, construction faible et contribution insuffisante.','Plus de procédure coercitive sur ces seuls critères ; contrôle des irrégularités et opérations volontaires conservés.')],repeal=True)
n='L481-1-2';body=p('Le présent article est abrogé à compter de l’entrée en vigueur de la loi portant cette abrogation.')+p('À compter de cette date, une société d’économie mixte n’est plus tenue, au titre du présent article, d’appartenir à un groupe de logement social en raison du nombre de logements qu’elle gère. Les seuils de taille du groupe ou de chiffre d’affaires fixés par cet article cessent de conditionner son respect. Aucune mise en demeure nouvelle de céder ou d’acquérir des logements, de souscrire une part d’une société de coordination ou d’en permettre la souscription ne peut être prise sur le seul fondement de l’obligation abrogée ; les procédures en cours sur ce seul fondement prennent fin.')+p('L’adhésion et le maintien volontaire dans un groupe demeurent possibles dans les conditions des articles L. 423-1-1 et L. 423-1-2 et des actes valablement conclus. La présente abrogation ne dissout aucun groupe, ne résilie aucun contrat et ne supprime ni la représentation des locataires ou du personnel ni les garanties financières applicables aux membres. Les obligations propres aux autres catégories d’organismes, fondées sur d’autres dispositions, ne sont pas modifiées par le présent article.')+p('Les opérations déjà valablement décidées, les contrats, les aides accordées, les créances et les recours antérieurs conservent leur régime : qualité technique et financière de l’acquéreur, plafonds d’accroissement de vingt pour cent sauf accord, compétence géographique lorsqu’elle était requise, fixation du prix après le désaccord de six mois et recours au juge. Aucun nouvel acte coercitif ne peut cependant être engagé après cette date sur le seul fondement abrogé. Les futurs regroupements volontaires peuvent bénéficier des concours de l’article L. 452-1 selon leurs conditions propres ; aucune aide ne devient automatique.')+p('Les conventions des logements, les droits des occupants et les contrôles financiers et de gestion demeurent applicables. Aucune déclaration de non-appartenance à un groupe n’est créée.')
add(n,body,'Supprimer le regroupement obligatoire desSEM en raison de leur taille et les cessions, acquisitions ou souscriptions forcées qui le sanctionnaient.','Les troisI/II/III et toutes exceptions ont été lus. L423-1-1/2 gardent groupes volontaires et contrôle interne des membres ; le régime historique maintenu aux sociétés déjà agréées en2018 et ses avantages fiscaux restent hors de cette abrogation. Les notes2021 et recodificationL351-2 sont historiques, pas dates de réforme. Pas de suppression de seuils ou règles imposés auxHLM par d’autres articles.','Les exceptions historiques des petitesSEM à activité accessoire, de chiffre d’affaires supérieur à40millions, d’unicité départementale, et des organismes ultramarins ou corses ne deviennent pas des conditions nouvelles : toute l’obligationSEM est supprimée. Aides, groupes volontaires et droits valablement acquis sont préservés.','material_reduction',[effect(n,'sem-concentration-forcee-supprimee','obligation_removed','qui gère moins de 12 000 logements sociaux appartient à un groupe','n’est plus tenue, au titre du présent article, d’appartenir à un groupe','Adhésion imposée avec seuils et mécanismes de cession/souscription forcés.','Adhésion volontaire, sans sanction de la seule taille ni déclaration de remplacement.')],repeal=True)
# Agréments sociaux : les principales coupes législatives sont déjà acquises dans le projet.
n='R365-2';t=S[n]['source_xml'];old="après avis du comité régional de l'habitat compétent ou de chaque comité régional de l'habitat compétent, lorsque l'organisme exerce son activité dans plusieurs régions. ";assert old in t;t=t.replace(old,'. ');t+=p('Conformément à l’article L. 365-2, aucun avis, saisine du comité régional ni copie de cet avis n’est demandé pour délivrer ou modifier l’agrément. Les pièces communes aux demandes d’agrément sont fournies une seule fois dans les conditions de cet article. Les contrôles des capacités, le délai de trois mois, la durée illimitée et le territoire fixé par l’agrément de maîtrise d’ouvrage demeurent applicables.')+p(T)
add(n,t,'Retirer la consultation régionale déjà supprimée par L365-2 du projet, en gardant tous les critères de capacité et le territoire de maîtrise d’ouvrage.','Coordination du même avis, pas nouveau gain. La première phrase et les6critères sont conservés, hors consultation. R365-6-1 garde préfet de région du siège ; la nationalité des agrémentsL365-3/4 n’est pas étendue par erreur à la maîtrise d’ouvrage.','Agrément initial, durée déjà illimitée et appui facultatif des fédérations conservés ; les exclusions HLM/SEM restent celles de la source et ne retirent aucun agrément de plein droit.','coordination_only',[effect(n,'agrement-social-avis-regional-supprime','coordination',"après avis du comité régional de l'habitat compétent",'aucun avis, saisine du comité régional ni copie de cet avis','Avis régional encore obligatoire dans le règlement.','Règlement aligné sur la suppression déjà proposée dans L365-2.')])
for n,leg in [('R365-3','L. 365-3'),('R365-4','L. 365-4')]:
 t=S[n]['source_xml'].replace('pour une durée de cinq ans renouvelable.','pour une durée indéterminée.');assert t!=S[n]['source_xml'];t+=p('L’agrément vaut sur l’ensemble du territoire national pour les seules activités qu’il couvre, conformément à l’article '+leg+'. Ni renouvellement périodique, ni agrément, autorisation ou déclaration d’extension territoriale n’est demandé. Les capacités énumérées ci-dessus restent appréciées pour la délivrance initiale ; les contrôles et le retrait contradictoire demeurent applicables. La durée, le territoire et les conditions des missions financées et des compensations de service public ne sont pas prolongés ou étendus par la seule portée de l’agrément.')+p('Les agréments valides, les demandes initiales en cours et les anciennes demandes de renouvellement ou d’extension sont régis par la transition de l’article '+leg+'. Aucun agrément retiré ou déjà caduc n’est rétabli ; aucune confirmation annuelle ou territoriale ne remplace les demandes supprimées.')
 add(n,t,'Coordonner la durée indéterminée et la portée nationale déjà fixées par '+leg+', sans compter une nouvelle suppression de renouvellement.','Tous les critères et le champ de l’organisme désintéressé restent. Les moyens nécessaires sont appréciés pour l’activité effectivement envisagée, pas un personnel à affecter d’avance dans chaque département français. Les notes historiques de L365 ne sont pas relancées.','Les agréments et dispenses de plein droit deR365-1 demeurent, les organismes valides bénéficient de la transition sans formalité, et aucun financement national illimité ou durée indéfinie de compensation n’est créé.','coordination_only',[effect(n,'agrement-social-duree-et-territoire-national','coordination','pour une durée de cinq ans renouvelable','pour une durée indéterminée','Règlement conservant cinq ans et renouvellement.','Même suppression législative rendue opératoire dans le règlement.')])
n='R365-5';t=S[n]['source_xml'].replace("ou du renouvellement de sa demande d'agrément", "d'agrément")
# Recomposer l’introduction pour ne pas doubler le motagrément.
t=t.replace("A l'appui de sa demande d'agrément prévu", "A l'appui de sa demande initiale d'agrément prévu")
t=t.replace("5° La décision de ses instances dirigeantes de solliciter un ou plusieurs des agréments prévus aux articles L. 365-2, L. 365-3 et L. 365-4 ;",'5° Abrogé ;').replace("9° Lorsqu'il est membre d'une union ou d'une fédération, la justification de son adhésion ;",'9° Abrogé ;')
t=t.replace("c) Une copie de l'avis du comité régional de l'habitat ou de chaque comité régional de l'habitat concerné par la demande d'agrément, saisis par ses soins.",'c) Abrogé.')
t+=p('La demande est présentée par le représentant légal dans la limite de ses pouvoirs ; aucune délibération spéciale des instances dirigeantes décidant de demander l’agrément n’est exigée comme pièce du dossier. L’exercice régulier de ses pouvoirs reste soumis aux règles propres de l’organisme. La seule qualité de membre d’une union ou d’une fédération ne donne pas lieu à une justification d’adhésion. Si l’organisme se prévaut d’un appui particulier de cette union ou fédération pour satisfaire un critère de capacité, la réalité de cet appui reste établie par les éléments utiles, sans imposer un certificat général d’adhésion.')+p('Les pièces communes aux différents agréments et les pièces déjà légalement disponibles sont traitées selon l’article L. 365-2. Aucun dossier de renouvellement ou d’extension territoriale des agréments des articles L. 365-3 et L. 365-4 n’est exigé ; les demandes de maîtrise d’ouvrage gardent leur régime territorial. La carte professionnelle reste exigée pour l’activité de gérance lorsqu’elle est légalement requise ; elle n’est pas remplacée par une simple déclaration.')+p(T)
add(n,t,'Supprimer deux pièces organiques du dossier initial : délibération spéciale pour demander l’agrément et preuve générale d’adhésion à une fédération. Coordonner aussi renouvellements et avis déjà supprimés.','Les1°/2°/3°/4°/6°/7°/8° et10°a/b, y compris budgets, comptes des deux derniers exercices, capacités et programme3ans restent.5°/9°/10°c demeurent repérés abrogés. Pas de suppression de la carte professionnelleHoguet ni des pouvoirs internes du représentant. Les autres dispenses sont celles de L365-2/3/4 déjà proposés, sans nouveaux gainsCRPA.','L’appui facultatif de la fédération peut toujours être pris en compte sans condition générale d’affiliation ; les organismes récents restent dispensés des comptes ou activités d’exercices inexistants. Tous agréments de plein droit et conditions favorables subsistent.','material_reduction',[effect(n,'agrement-social-pieces-organiques-supprimees','obligation_removed','La décision de ses instances dirigeantes de solliciter un ou plusieurs des agréments','aucune délibération spéciale des instances dirigeantes','Délibération spéciale à joindre et certificat général d’adhésion demandé aux membres.','Ces deux pièces ne sont plus obligatoires dès la demande initiale ; pouvoirs du représentant et preuve d’un appui réellement invoqué restent.')],['Délibération spéciale des instances dirigeantes demandée comme pièce du dossier initial d’agrément.','Justification générale d’adhésion à une union ou une fédération à joindre dès que le demandeur en est membre.'])
n='R365-6';body=p('La demande initiale d’agrément relative à l’ingénierie sociale, financière et technique ou à l’intermédiation locative et à la gestion locative sociale est présentée par le représentant légal de l’organisme au préfet du département dans lequel l’activité initialement envisagée est exercée. Lorsque cette activité est initialement envisagée dans plusieurs départements d’une même région, elle est présentée au préfet de région. Lorsque plusieurs régions sont concernées dès cette demande, le préfet de la région du siège social de l’organisme est saisi. Une seule demande est nécessaire pour les activités relevant du même agrément ; les pièces communes suivent l’article L. 365-2.')+p('La demande est transmise par une voie légalement ouverte permettant d’établir sa réception. Elle peut être remise contre récépissé lorsque l’autorité propose ce mode de réception. Aucun envoi recommandé exclusif n’est requis du seul fait du présent article. Les données et pièces nécessaires de l’article R. 365-5 demeurent fournies dans les limites de cet article.')+p('Pour l’instruction initiale d’une demande intéressant plusieurs départements d’une région, le préfet de région consulte les préfets de département concernés. Le préfet compétent dispose de trois mois à compter de la réception du dossier complet pour se prononcer. L’avis des préfets ne constitue pas une autorisation territoriale supplémentaire du bénéficiaire.')+p('L’agrément délivré est national dans les conditions des articles L. 365-3 et L. 365-4. Il ne devient pas caduc lors d’une extension d’activité ; aucune nouvelle demande ni consultation départementale d’extension, autorisation, déclaration ou confirmation ne sont exigées. Les contrôles de l’activité et le retrait contradictoire prévu à l’article R. 365-8 restent applicables.')+p(T)
add(n,body,'Permettre une réception régulière sans recommandé exclusif, et exécuter la suppression législative des nouvelles demandes d’extension territoriale.','Délai3mois et consultation préfectorale initiale dans une région conservés. La compétence pour la demande initiale multirégionale est rendue explicite au siège pour éviter de recréer plusieurs agréments nationaux. Ce choix n’impose aucun dossier ou guichet supplémentaire. La voie électronique déjà légalement ouverte n’est pas un gain nouveau ; l’alternative papier régulièrement reçue est la coupe distincte.','Les organismes conservent leurs agréments nationaux et leurs dispenses de plein droit ; les demandes en cours gardent les délais courus et aucun agrément valide ne devient caduc lors de l’extension. Aucun financement ou mandat local n’est automatiquement étendu.','material_reduction',[effect(n,'agrement-social-envoi-recommande-non-exclusif','obligation_removed','par lettre recommandée avec demande d’avis de réception','Aucun envoi recommandé exclusif n’est requis','Lettre recommandée obligatoire selon le règlement pour saisir le préfet.','Voie légalement ouverte établissant la réception, y compris remise contre reçu si proposée ; déclaration d’extension supprimée conformément à la loi.')],['Exclusivité de la lettre recommandée comme mode de transmission de la demande initiale.','Nouvelle demande, caducité et consultations départementales pour la seule extension d’un agrément déjà rendu national par L365-3/4.'])
n='R365-7';body=p('L’envoi annuel automatique d’un compte rendu de l’activité et des comptes financiers à l’autorité ayant délivré les agréments des articles L. 365-2, L. 365-3 et L. 365-4 n’est plus exigé sur le fondement du présent article. Aucun rapport annuel, dépôt périodique ou attestation de maintien de l’agrément ne le remplace.')+p('L’autorité administrative peut à tout moment contrôler les conditions d’exercice de l’activité de l’organisme dans le cadre de ses compétences. Les comptes et documents d’activité déjà établis selon les obligations comptables ou les conventions légalement maintenues restent disponibles pour ces contrôles ; leur communication est régie par les pouvoirs légalement applicables. Le présent article ne crée aucun nouveau rapport ou accès à des données protégées.')+p('Toute modification statutaire est notifiée sans délai à l’autorité administrative.')+p('La suppression de l’envoi annuel s’applique aux échéances postérieures à l’entrée en vigueur de la réforme, même si elles concernent un exercice antérieur. Aucun rattrapage de cet envoi n’est exigé après cette date. Les comptes, conventions et rapports déjà établis restent utilisables ; les obligations autonomes de comptabilité, de suivi des financements et de contrôle des compensations de service public subsistent.')
add(n,body,'Supprimer l’envoi annuel automatique du rapport d’activité et des comptes pour les trois agréments, sans dossier périodique de remplacement.','Les contrôles à tout moment et la notification des modifications statutaires sont conservés, ainsi que les obligations comptables et les conventions de financement autonomes. Il s’agit d’un dépôt périodique retiré, même quand l’administration ne détenait pas encore les comptes, distinct du simple principeCRPA. L’agrément national indéfini n’entraîne ni droit à compensation perpétuelle ni disparition du contrôle des aides.','Les agréments, aides et conventions valides conservent leur effet, les organismes nouveaux ne supportent pas un rapport annuel recréé et les droits des bénéficiaires restent protégés par les règles de fond et les contrôles maintenus.','material_reduction',[effect(n,'agrement-social-envoi-annuel-supprime','obligation_removed','sont adressés annuellement à l’autorité administrative','L’envoi annuel automatique d’un compte rendu','Transmission annuelle du compte rendu d’activité et des comptes à l’autorité d’agrément.','Suppression du dépôt périodique, comptes et contrôles conservés sans rapport de remplacement.')],['Transmission annuelle automatique du compte rendu d’activité et des comptes financiers à l’autorité d’agrément.'])
# SEM : agrément initial utile aux avantages SIEG, mais pas agréments répétés parterritoire.
n='R481-1';t=S[n]['source_xml'];old="après avis du Comité régional de l'habitat et de l'hébergement compétent pour la région dans laquelle la société a son siège. ";assert old in t;t=t.replace(old,'. ');t+=p('La délivrance initiale de l’agrément n’est pas subordonnée à un avis préalable du comité régional de l’habitat et de l’hébergement. L’agrément demeure soumis à l’examen des informations nécessaires sur la société, son activité et ses projets ; il ne dispense ni du contrôle de l’Agence nationale de contrôle du logement social ni des conditions des aides et des missions de service d’intérêt économique général.')+p(T)
add(n,t,'Supprimer l’avis régional préalable à l’agrément initialSEM, en gardant décision ministérielle, dossier de capacité et contrôle.','Avis initial distinct de la consultation protectrice avant retraitR481-1-4, qui est conservée. Pas d’abrogation de l’agrément L481-1 ni de qualificationSIEG. L’arrêté de dossier reste à adapter pour ne pas réclamer cet avis ou saisine par le demandeur.','Les agréments de plein droitL481-1, les aides, exonérations, activités subsidiaires et statuts antérieurs sont conservés ; l’avis supprimé n’est remplacé par aucune attestation ni demande locale.','material_reduction',[effect(n,'sem-avis-regional-agrement-initial-supprime','obligation_removed',"après avis du Comité régional de l'habitat et de l'hébergement",'n’est pas subordonnée à un avis préalable','ConsultationCRHH obligatoire pour agrément initial.','Décision initiale du ministre sans cette consultation, contrôle et garanties de retrait maintenus.')],['Avis préalable du comité régional pour la seule délivrance initiale de l’agrémentSEM.'])
n='R481-1-1';body=p('Les sociétés d’économie mixte agréées en application de l’article L. 481-1 sont habilitées, au titre de cet agrément, à exercer les activités de construction et de gestion de logements sociaux qu’il couvre sur l’ensemble du territoire national. L’extension territoriale ne requiert ni agrément ministériel spécial, ni extension préfectorale pour une opération déterminée, ni accord de la commune d’implantation sur le seul fondement du présent article.')+p('Cette portée nationale ne modifie ni l’objet social ni les compétences légalement dévolues à la société, ni les actes lui confiant une mission de service public, ni le territoire ou les conditions des conventions, aides, garanties et financements accordés. Les autorisations d’urbanisme et les accords ayant un fondement distinct restent applicables. Les exigences de qualité technique et financière et les contrôles ANCOLS sont conservés ; ils ne donnent lieu à aucune autorisation territoriale de remplacement.')+p('Les agréments en cours de validité à l’entrée en vigueur de la réforme bénéficient de plein droit de cette portée pour les activités agréées, sans demande ni déclaration. Les demandes d’extension ou d’agrément national en cours deviennent sans objet ; les demandes initiales restent instruites sans nouveau dépôt ni reprise des délais. Les agréments retirés ou caducs ne sont pas rétablis. Les contrats, financements, droits des occupants et accords valablement constitués conservent leur régime propre.')
add(n,body,'Retirer les agréments territoriaux successifs et l’accord communal spécifique : l’agrémentSEM initial couvre les activités agréées nationalement.','Source et R481-1-2/3 entiers lus. Les contrôles de capacité, les compétences propres de la société et ses mandats/financements ne sont pas élargis par magie. R481-1-4 garde le retrait contradictoire pour incapacité technique/financière, éventuellement partiel. Les bénéficiaires de plein droit sont expressément coordonnésR481-1-3.','L’accès à la portée nationale ne dépend plus de7500logements ; les agréments valides et anciens agréments nationaux sont préservés. Toutes aides et exonérations futures restent soumises à leurs propres conditions sans financement national automatique.','material_reduction',[effect(n,'sem-agrement-territorial-unique','obligation_removed','Le ministre chargé du logement peut agréer spécialement les sociétés','L’extension territoriale ne requiert ni agrément ministériel spécial','Agrément régional, accord communal voisin, agrément de régions limitrophes et extension préfectorale d’opération.','Agrément initial national pour ses activités, sans actes territoriaux répétés ni déclaration de remplacement.')],['Agréments spéciaux ministériels et extensions préfectorales pour étendre le territoire d’une activitéSEM déjà agréée.','Accord communal préalable imposé pour intervenir dans les départements limitrophes au titre de cet agrément.'])
n='R481-1-2';body=p('Le présent article est abrogé à compter de l’entrée en vigueur du décret portant cette abrogation.')+p('L’agrément spécial national et le seuil de sept mille cinq cents logements qu’il prévoyait ne sont plus exigés, l’agrément de l’article L. 481-1 ayant la portée définie à l’article R. 481-1-1. Aucun certificat, évaluation préalable supplémentaire ou déclaration d’extension ne les remplace. Les contrôles techniques et financiers légalement applicables restent requis.')+p('Les agréments nationaux déjà délivrés restent valides. Les demandes d’extension nationale en cours deviennent sans objet sans nouveau dépôt ; les droits, conventions et financements antérieurs ne sont pas supprimés. La portée de l’agrément n’étend pas automatiquement les mandats de service public, les aides ou les compétences propres de la société.')
add(n,body,'Abroger le second circuit d’agrément national et son seuil, déjà rendus sans objet par l’agrément territorial unique du lot.','Même dispositif queR481-1-1, zéro seconde suppression comptée. Note2021contributions/prestations2012? sourceentrée2022 conservée dans référence, pas élargie aux actes futurs.','L’ancienne faculté favorable nationale est ouverte à tous les agréments concernés, non fermée pour l’avenir ; tous agréments nationaux et financements valides restent, sans exigence de nouvelle demande.','coordination_only',[effect(n,'sem-agrement-territorial-unique','coordination','au moins 7 500 logements conventionnés','ne sont plus exigés','Second agrément national avec seuil7500.','Même portée nationale rendue accessible sans second agrément.')],repeal=True)
n='R481-1-3';body=p('Les sociétés d’économie mixte bénéficiant de l’agrément de droit prévu au troisième alinéa de l’article L. 481-1 conservent cet agrément. Elles bénéficient, pour les activités qu’il couvre, de la portée territoriale prévue à l’article R. 481-1-1 sans nouvel agrément, accord communal particulier ou déclaration d’extension.')+p('Les implantations, conventions et droits antérieurement constitués, notamment ceux liés au patrimoine détenu au 26 mars 2014, ne sont pas remis en cause. Les conventions des logements, les conditions des aides et les autres autorisations ayant un fondement distinct demeurent applicables. Les dispositions transitoires de l’article R. 481-1-1 s’appliquent à ces sociétés.')
add(n,body,'Conserver l’agrément de droit2014 et lui appliquer la même extension nationale sans dossier supplémentaire.','La date26mars2014 n’est pas déplacée ni transformée en condition de retrait. L’ancienne limite régionsdupatrimoine/départementslimitrophes est supprimée pour les activités agréées, sans extension des mandats et aides.','Tous bénéficiaires de l’agrément de plein droit restent bénéficiaires pour les opérations futures ; aucun retour à une demande initiale ni perte d’aide ou de convention antérieure.','coordination_only',[effect(n,'sem-agrement-territorial-unique','coordination','après accord de la commune d’implantation de l’opération','sans nouvel agrément, accord communal particulier','Portée initiale liée au patrimoine2014 et accord voisin.','Bénéfice de plein droit préservé et même portée nouvelle, sans seconde démarche.')])
n='R481-1-4';t=S[n]['source_xml'].replace("comité régional de l'habitat et de l'hébergement mentionné à l'article R. 481-1",'comité régional de l’habitat et de l’hébergement compétent pour la région du siège de la société');t+=p('La portée nationale de l’agrément ne supprime ni ce contrôle de capacité ni les garanties contradictoires et l’avis prévus au présent article. Un retrait territorial partiel demeure possible si ses conditions sont réunies, sans rétablir une obligation générale de demander des extensions territoriales.')
add(n,t,'Conserver l’avis protecteur avant retrait et préciser sa compétence après suppression du seul avis d’agrément initial.','Le défaut technique/financier, retrait total/partiel, observationsL342-12 et arrêtéministre restent. La désignation directe duCRHH évite un renvoi ambigu après modificationR481-1 ; aucune nouvelle consultation n’est créée.','La défense contradictoire et l’avis avant retrait protègent les titulaires ; les agréments valides ne sont pas retirés du seul fait de la nouvelle portée nationale.','coordination_only',[effect(n,'sem-avis-regional-agrement-initial-supprime','coordination',"après avis du comité régional de l'habitat",'les garanties contradictoires et l’avis','Avis avant retrait renvoyant au comité de l’article d’agrément initial.','Même avis avant retrait et contradictoire, autorité identifiée directement.')])
n='D481-5-2';t=S[n]['source_xml'].replace('La périodicité trimestrielle ou semestrielle de la reddition des comptes et ses modalités.','La périodicité et les modalités de la reddition des comptes convenues entre les parties.');t+=p('La reddition des comptes n’est pas soumise à une périodicité trimestrielle ou semestrielle obligatoire sur le seul fondement du présent article. Elle demeure due et son contenu n’est pas supprimé. Lorsque le mandant est doté d’un comptable public, les échéances permettant de produire le compte financier et les règles du V de l’article D. 481-5-7 restent impératives. Les autres obligations légales de reddition et de protection des fonds ne sont pas modifiées.')+p('La faculté de convenir d’une autre périodicité s’applique aux nouveaux mandats et aux avenants valablement conclus après l’entrée en vigueur de la réforme. Les échéances et créances de reddition déjà prévues par les mandats demeurent, sans modification unilatérale ; aucune renégociation n’est obligatoire.')
add(n,t,'Supprimer la fréquence trimestrielle ou semestrielle imposée à tout mandat ; laisser les parties choisir la périodicité avec reddition obligatoire et échéances publiques conservées.','Les6rubriques, écrit du mandat, immeubles, durée/résiliation, pouvoirs, fonds/avance, rémunération restent. Pas suppression de reddition ni de la comptabilité séparée, assurance et fonds dédiésD481-5-3à7. Les mandats en cours restent contractuellement opposables.','La faculté des parties de convenir du rythme ne retire ni au mandant ses comptes ni au locataire la protection des fonds. Le délai du compte financier public reste ; aucun minimum annuel nouveau ni dispense de justificatifs financiers n’est inventé.','material_reduction',[effect(n,'sem-mandat-periodicite-comptes-libre','obligation_removed','La périodicité trimestrielle ou semestrielle','n’est pas soumise à une périodicité trimestrielle ou semestrielle obligatoire','Reddition obligatoirement trimestrielle ou semestrielle pour tout mandat.','Périodicité convenue, sous échéances publiques et autres obligations impératives maintenues.')],['Périodicité uniformément trimestrielle ou semestrielle imposée à la reddition des comptes du mandat.'])
n='R481-6';t=S[n]['source_xml']+p('Pour l’application aux sociétés d’économie mixte du 3° de l’article R. 422-2-1, les conditions tenant à l’association qui présente une liste sont celles de l’article L. 481-6. L’absence d’affiliation à une organisation nationale n’est pas un motif d’irrecevabilité de la liste ; l’indication de l’affiliation sur les documents électoraux n’est requise que si une telle affiliation existe. Les règles du scrutin, les conditions personnelles d’électorat et d’éligibilité, les mandats et les recours demeurent inchangés. Cette coordination suit la transition électorale de l’article L. 481-6, sans réouverture de délais expirés.')
add(n,t,'Empêcher que le renvoi électoral auR422-2-1 rétablisse l’affiliation nationale déjà retirée deL481-6.','R422-2-1 source/notes entière lue : son3° renvoie aux conditions associatives et exige l’indication d’affiliation. La dérogationSEM seule est précisée, sans modifier lesHLM, le protocole national ou supprimer les droits de concertation des listes. Tous nombres/mandats/remplacementsR481-6 restent.','Les listes locales éligibles restent recevables sans affiliation nationale, avec scrutinsecret, représentation proportionnelle, recours et mandats conservés. Aucun certificat de non-affiliation nouveau.','coordination_only',[effect(n,'sem-listes-locataires-sans-affiliation-nationale','coordination','dans les conditions prévues aux 3° et 4° de l’article R. 422-2-1','L’absence d’affiliation à une organisation nationale n’est pas un motif','Renvoi électoral susceptible de rétablir condition nationale supprimée.','Même ouverture législative rendue effective pour lesSEM ; autres garanties inchangées.')])
for n,old,new,why in [('D481-9','D. 442-3-1','R. 442-3-1','perte d’autonomie et justificatifs existants'),('D481-10','D. 442-3-2','R. 442-3-2','aide à la mobilité, forfaits et indexation')]:
 t=S[n]['source_xml'].replace(old,new);assert t!=S[n]['source_xml'];t+=p('Cette coordination de référence ne réduit ni le champ des bénéficiaires, ni les exceptions favorables, ni les montants, délais, indexations ou modalités de preuve légalement applicables à cet avantage. Les demandes et droits déjà constitués demeurent recevables selon leur régime propre.')
 add(n,t,'Rétablir le renvoi effectif vers la cible actuelle du corpus pour '+why+', sans modifier l’avantage.','LeD ancien n’est pas une cible actuelle de l’inventaire ; leR correspondant existe et son corps entier a été lu. Pas nouveau calcul de plafonds ni nouveaux seuilsCSS ; simple concordance réglementaire à contrôler avec l’acte de recodification lors de la mise en forme finale.','L’avantage reste ouvert aux futures situations éligibles et aux droits en cours ; toutes variantes favorables et obligations du bailleur de la cible restent, sans nouvelle attestation pour cette coordination.','coordination_only',[effect(n,'sem-renvois-aides-et-autonomie-effectifs','coordination',old,new,'RenvoiD sans cible actuelle correspondante dans le corpus.','RenvoiR actuel au même dispositif favorable, sans changement de contenu.')])
n='D481-14';body=p('Le présent article est abrogé à compter de l’entrée en vigueur du décret portant cette abrogation.')+p('Les sociétés d’économie mixte ne sont plus tenues, sur son seul fondement, de transmettre après l’assemblée générale au préfet, au ministre chargé du logement ou à la Caisse de garantie du logement locatif social les copies des documents annuels, le procès-verbal, les états réglementaires ou la décision de justice reportant cette assemblée. Aucun dépôt annuel équivalent, nouvelle plate-forme ou attestation de non-transmission ne remplace cette formalité.')+p('Cette suppression s’applique aux transmissions à effectuer après cette date, même si elles concernent un exercice antérieur. Aucun dépôt de rattrapage n’est demandé sur ce fondement ; les documents déjà transmis restent utilisables sans nouvelle production. Les obligations comptables, la présentation distincte du résultat social, les dépôts légaux auprès des registres, les conventions de financement et les contrôles légalement applicables demeurent. Les documents existants nécessaires à un contrôle peuvent être demandés selon les pouvoirs qui régissent ce contrôle, sans obligation de créer le relevé annuel supprimé.')+p('Les comptes et les droits, créances, aides et engagements antérieurs conservent leur régime propre. Les exigences autonomes de contrôle des compensations de service public ne sont pas supprimées. L’arrêté fixant le format de cet envoi ne peut maintenir sa transmission annuelle sur le seul fondement abrogé.')
add(n,body,'Supprimer le circuit annuel réglementaire de copies et d’états après assemblée, en cohérence avec L481-8, sans supprimer les comptes et contrôles.','L481-8 a déjà retiré l’envoi au ministre et son habilitation. La suppression réglementaire retire aussi les destinataires préfet/CGLLS et la transmission de la décision de report, sur ce seul fondement ; champ complémentaire tracé, pas trois nouvelles procédures ou un gainCRPA. Comptabilité distincteL481-1 et présentationD481-15 conservées. Les arrêtés de format/plate-forme sont à coordonner matériellement, sans prétendre les avoir publiés.','Aides et garanties ne sont pas conditionnées à un dépôt annuel de remplacement ; les comptes de service d’intérêt général, droits des actionnaires/locataires et contrôles du bon emploi des fonds sont conservés, y compris pour les situations futures.','coordination_only',[effect(n,'sem-comptes-annuels-transmission-supprimee','coordination','adressent au préfet du département de leur siège social','ne sont plus tenues, sur son seul fondement, de transmettre','Circuit annuel au ministre, préfet etCGLLS avec états et éventuelle décision de report.','Suppression réglementaire du même dépôt annuel déjà retiré législativement pour le ministre ; extension de portée aux autres destinataires, sans suppression des comptes.')],repeal=True)
# Les normes essentielles restent textuellement conservées ; motifs propres à chaque dispositif.
retained={
 'L481-1':('L’agrément initial qualifie laSEM pour aides et exonérationsSIEG ; comptabilité distincte etANCOLS protègent les actifs sociaux. Les circuits répétés sont retirés dans les règlements sans fermer cette qualification.','Agrément de plein droit2014, résidences universitaires, logements des servicespublics et avantages fiscauxSIEG restent ouverts ; aucune suppression de comptabilité distincte.'),
 'L481-3':('Les trois offres conformes de relogement, la solution spécialement conçue et le préavis de sixmois encadrent le congé pour démolition ; les retirer sans réforme du relogement affaiblirait les occupants.','L’alternative favorable du logement spécialement conçu demeure ; pas de perte de protection ni nouveau motif de congé.'),
 'L481-4':('Les règles de commande publique relèvent de leur champ légal et européen autonome ; une suppression de renvoi ne permet pas de les écarter et n’en prouverait aucune économie.','Pas de nouveau marché obligatoire ni perte de faculté contractuelle ; les exclusions du code de la commande publique demeurent dans leur champ.'),
 'L481-5':('Le champ d’application des protectionsL482 et des logements ultramarins aidés est nécessaire ; la note2019 substitue déjà les référencesAPL auL351-2 sans créer une démarche.','Conserver toutes catégories de logements aidés et droits de mobilité/relogement ; pas de suppression stylistique de l’ancien renvoi automatiquement coordonné.'),
 'L481-7':('La délégation nécessaire au gestionnaire est une habilitation favorable, pas une autorisation supplémentaire à supprimer.','Toutes catégories de mandants restent, association etSCI détenues99% comprises ; les délégations utiles demeurent.'),
 'L482-1':('Relogement à loyer inférieur et hors plafond de ressources, aide mobilité et exemptions âge/handicap/autonomie/QPV protègent les locataires ; aucun allègement administratif ne justifie leur retrait.','Trois offres, sixmois, plus65ans, handicap/autonomie, quartiers et anciensZUS protégés intégralement ; pas de contrainte nouvelle.'),
 'L482-2':('Logementadapté libéré : relogement, loyer inférieur et aides avec préavis6/18mois et protectionplus65ans sont nécessaires ; pas de suppression de ces droits.','Exception de18mois en cas de décès de personnehandicapée àcharge conservée, plafonds de ressources écartés et aide du bailleur maintenue.'),
 'L482-5':('La clause de fonction reste facultative et coordonnée aux garanties deL442-7, lu entier ; aucune nouvelle limitation du maintien dans les lieux n’est justifiée.','Délai d’un an de décision employeur, préavis au moins6mois, situationsexceptionnelles ethandicap restent dans leur régime ; pas d’effacement des protections par la clause.'),
 'R365-1':('Le catalogue définit les activités finançables et plusieurs agréments de plein droit. Le conserver prévient une nouvelle demande pour des opérateurs déjà qualifiés.','Toutes assimilations sociales, accompagnementDALO de plein droit et gestion des biens propriétaires/preneurs sont maintenus ; aucune prestation aidée perdue.'),
 'R365-6-1':('Pour la maîtrise d’ouvrage seulement, compétence du préfet de région du siège préservée ; la nationalisationL365-3/4 ne doit pas supprimer ce circuit propre.','Aucune extension territoriale nouvelle exigée ; les agrémentsMO déjà sans limite de durée et leurs possibilités d’extension restent selon leur champ.'),
 'R365-8':('Retrait pour perte des conditions ou manquementgrave/répété, avec observations préalables, reste nécessaire après suppression du renouvellement.','Garanties contradictoires et possibilité de conserver l’agrément en respectant ses conditions maintenues, sans confirmation annuelle.'),
 'R481-2':('Règle de substitution évitant des régimes locatifs concurrents, pas un document autonome ; aucune seconde procédure nouvelle n’est imputée au renvoi.','ConventionsAPL et droits locatifs restent dans leurs champs, sans étendre les régimes non applicables.'),
 'R481-3':('Le renvoi aux règles de contrats reste sous leurs conditions propres ; leur suppression sans étude de chaque disposition et de la commande publique ne serait pas une coupe démontrée.','Aucune dispense contractuelle existante n’est retirée ; le statut courant des référencesR433-5à23 n’est pas présenté comme intégralement vérifié dans ce lot.'),
 'R481-4':('Le champ du supplément de loyer et son exceptionR441-31 ne créent pas un justificatif distinct. Pas de suppression du régime par simple renvoi.','Les exclusions géographiques, des prêts conventionnés/autresbailleurs,immeublesloyermoyenDOM et subventionsANAH deR441-31 restent intégrales.'),
 'R481-5':('La commission d’attribution et son fonctionnement garantissent les droits des demandeurs ; aucun dossier doublonné autonome dans ce seul renvoi.','Les droits et voies de candidature aux logementsconventionnés demeurent ; aucun quotaSRU n’est ajouté.'),
 'R481-5-1':('Application des droits de réduction de loyer, conventions et gestion sociale ; les dispensesL481-2 du projet restent de niveau supérieur sans nouveau dépôt.','Exceptions aux logements et droitsAPL conservés ; aucun retour des autorisations de gérance suppriméesL481-2 par ce renvoi.'),
 'D481-5-3':('Assurance de responsabilité civile avant mandat protège mandant et victimes des actes du gestionnaire ; supprimer cette garantie n’est pas une simple coupe documentaire.','Toutes voies de couverture légalement admises restent ; aucun certificat ou assureur imposé nouveau.'),
 'D481-5-4':('Mention du mandant et du pouvoir exercé informe les tiers et empêche la confusion des engagements ; aucun formulaire ou dépôt indépendant.','Les délégations utiles demeurent avec identification du responsable ; pas de nouvelle formalité périodique.'),
 'D481-5-5':('Comptabilité séparée et interdiction d’avancer les fonds hors urgence protègent les deniers confiés, distincts du dépôt annuel supprimé.','Exception favorable d’urgence et mise à disposition des fonds par le mandant conservées ; pas de financement automatique imposé au gestionnaire.'),
 'D481-5-6':('Compte exclusivement dédié aux fonds du mandant protège leur ségrégation ; sa suppression transférerait un risque de confusion des patrimoines.','Aucun nouvel établissement teneur de compte ou frais forfaitaire n’est imposé ; les garanties existantes restent.'),
 'D481-5-7':('Contrôle du mandat et reddition publique avec pièces comptables sont nécessaires à la responsabilité sur les fonds. Pas suppression d’un avis ou délai comptable sans étude du régime public autonome.','Choix desétablissementsUE/EEE, avis taciteunmois et limites d’avance préservés. Les référencesR481-5-6 et loi1991 sont des anomalies/concordances à traiter séparément, pas une validation de tous les renvoisCPCE.'),
 'R481-5-8':('Désignation du représentant et délégation de signature sont des possibilités de gestion, pas une autorisation administrative préalable à supprimer.','La délégation sous responsabilité reste ouverte à tous les bénéficiaires prévus ; pas de formalité nouvelle.'),
 'R481-7':('Accession sociale et définitionSIEG constituent un régime de droits à préserver ; aucun nouveau dépôt distinct démontré dans ce renvoi.','Les possibilités d’accession restent dans leur champ, sans prétendre réécrire toutes les conditionsR443-2 dans cette passe.'),
 'R481-8':('Le renvoi à l’accession progressive est favorable et se coordonne déjà auIIL481-2 ; l’abroger fermerait le régime.','Garanties de rachat et droits progressifs d’acquisition demeurent, sans nouvelle déclaration ou retour des quotasSRU.'),
 'R481-8-1':('Champ des ventes, exclusionR443-12-3 et publicité existante protègent acheteurs/locataires ; pas de nouvelle suppression fiscale par ce renvoi.','Métropole/DOM/SaintMartin, exceptions et ventes des logementsvacants conservent leurs champs ; aucun avantage supprimé.'),
 'R481-8-2':('Plafonds de redevance deslogementsfoyers et indexation encadrent les coûts desoccupants ; pas suppression sans étude économique et droits acquis.','Tous territoires, I/II/III, révision1janvier et référenceL353-9-2 conservés. Le21doublé est une anomalie typographique source, pas une nouvelle coupe.'),
 'R481-11':('Le zonage limite les cas de perte du droit au bail desL482-3/3-1 ; son retrait pourrait étendre une contrainte au lieu de la réduire.','Conserver champgéographique et exemptions despersonnesâgées/handicap/QPV ; pas de quotaSRU réintroduit.'),
 'R481-12':('Application de la révision des situationslocatives dans les seuls logementsconventionnés ; aucune pièce administrative distincte à supprimer à ce seul niveau.','Les exceptions, droits et contrôles des dispositions de fond restent ; la note2022 n’est pas déplacée vers la réforme future.'),
 'D481-15':('Présentation comptable du résultatSIEG conserve traçabilité des compensations après suppression de leur envoi annuel ; ce n’est pas le dépôt supprimé.','Les régimes fiscaux et financementsSIEG restent qualifiés, sans taux de dividende ou d’ISnouveau.'),
 'D481-16':('Les avances/prêts demeurent sousL481-8 etL423-15/16 ; retirer ici tout dossier sans traiter ces règles réintroduirait une contradiction avec les protections des fonds.','Les prêts et avances autorisés restent possibles avec leurs seuils/conditions ; aucune déclarationSGA déjà supprimée n’est rétablie. D423-1-1à3 entiers lus, périmètre des demandes conservé.')}
for n,(why,benefit)in retained.items():
 add(n,None,'Maintien nécessaire du texte source : '+why,'Source et notes entières lues. '+why+' Aucune réécriture stylistique ne sert de gain. Les limites de contrôle des renvois horslot sont explicitement distinguées dans l’audit.',benefit,'retained_necessary')
